/*
 * Notificações no formato do menu do usuário do Discourse.
 *
 * O Flarum não agrupa as notificações por tipo no servidor (não há filtro
 * `type` na API), então as abas filtram no cliente, pelo `contentType()`, o
 * que o `app.notifications` já carregou. Os textos vêm dos componentes que
 * cada extensão registra (`app.notificationComponents`): o tema só muda a
 * forma — avatar de quem gerou com o ícone do tipo num selo, nome em negrito
 * e o título do tópico, como o `.user-menu.show-avatars` do Discourse.
 */
import app from 'flarum/forum/app';
import Avatar from 'flarum/common/components/Avatar';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import classList from 'flarum/common/utils/classList';
import extractText from 'flarum/common/utils/extractText';
import { userMenu } from './state';

/** As abas que filtram notificações: "Respostas" é o `replies` do Discourse (mencionado, citado, respondido, postado). */
export const REPLY_TYPES = ['newPost', 'postMentioned', 'userMentioned', 'groupMentioned'];
/** `postReacted` é o tipo das reações (fof/reactions), que o Discourse também põe em Curtidas. */
export const LIKE_TYPES = ['postLiked', 'postReacted'];
export const MESSAGE_TYPES = ['messageReceived'];
export const BOOKMARK_TYPES = ['canelaBookmarkReminder'];
/** Tudo o que o `app.notifications` já carregou, na ordem da API (mais novas primeiro). */
export function loadedNotifications() {
  const state = app.notifications;
  if (!state || typeof state.getPages !== 'function') return [];
  const list = [];
  state.getPages().forEach(page => {
    (page.items || []).forEach(notification => list.push(notification));
  });
  return list;
}
export function matches(notification, filter) {
  const type = notification.contentType() || '';
  if (filter.types && !filter.types.includes(type)) return false;
  if (filter.exclude && filter.exclude.includes(type)) return false;

  // Sem componente registrado (extensão desligada) não há como desenhar.
  return !!app.notificationComponents?.[type];
}
export function filteredNotifications(filter) {
  return loadedNotifications().filter(notification => matches(notification, filter));
}

/** O número da bolha de uma aba: as não lidas daquele grupo entre as carregadas. */
export function unreadCount(filter) {
  return filteredNotifications(filter).filter(notification => !notification.isRead()).length;
}

/** Como o `Notification.markAsRead()` do core, para itens que não são o componente dele. */
export function markNotificationRead(notification) {
  if (notification.isRead()) return Promise.resolve();
  const user = app.session.user;
  user?.pushAttributes({
    unreadNotificationCount: Math.max(0, (user.unreadNotificationCount() ?? 0) - 1)
  });
  return notification.save({
    isRead: true
  }).catch(() => {});
}

/**
 * "Descartar": sem filtro, o POST /notifications/read do core (todas). Com
 * filtro, só as não lidas daquele grupo, uma a uma — o Flarum não tem o
 * `dismiss_types` do Discourse.
 */
export function dismissNotifications(filter) {
  if (!filter || !filter.types && !filter.exclude) {
    return Promise.resolve(app.notifications.markAllAsRead()).then(() => m.redraw());
  }
  const unread = filteredNotifications(filter).filter(notification => !notification.isRead());
  return Promise.all(unread.map(notification => markNotificationRead(notification))).then(() => m.redraw());
}
function relatedDiscussion(notification) {
  const subject = notification.subject();
  if (!subject) return null;
  if (subject.data?.type === 'discussions') return subject;
  if (typeof subject.discussion === 'function') return subject.discussion() || null;
  return null;
}
/**
 * O que o Discourse mostra numa notificação: quem gerou (`item-label`, em
 * negrito) e o título do tópico (`item-description`), com o tipo só no ícone.
 * Sem tópico ou sem outra pessoa (um emblema ganho, uma suspensão), o texto
 * do próprio componente vira a descrição, sem rótulo — como o "Ganhou
 * 'Primeira curtida'" do Meta. A frase inteira fica no `title`.
 */
export function describeNotification(notification) {
  const Component = app.notificationComponents?.[notification.contentType() || ''];
  if (!Component) return null;

  // Os métodos dos componentes só leem `this.attrs.notification`: dá para
  // usá-los sem montar o componente (e sem o HeaderListItem dele).
  const instance = new Component();
  instance.attrs = {
    notification
  };
  const call = (method, fallback) => {
    try {
      const value = instance[method]?.();
      return value === undefined || value === null ? fallback : value;
    } catch (e) {
      return fallback;
    }
  };
  const content = call('content', '');
  const title = extractText(content);
  const fromUser = notification.fromUser();
  const discussion = relatedDiscussion(notification);
  const other = fromUser && fromUser !== app.session.user;
  return {
    icon: call('icon', 'fas fa-bell'),
    href: call('href', ''),
    label: other && discussion ? fromUser.displayName() : null,
    description: other && discussion ? discussion.title() : content,
    title
  };
}

/** Sem pessoa (o "system" do Discourse): o ícone do fórum no lugar do avatar. */
function systemAvatar() {
  const src = app.forum.attribute('faviconUrl') || app.forum.attribute('logoUrl');
  return src ? m("img", {
    className: "Avatar CanelaUserMenu-systemAvatar",
    src: src,
    alt: "",
    loading: "lazy"
  }) : m(Avatar, {
    user: null
  });
}

/** O `.icon-avatar` do Discourse: avatar de 2em com o ícone do tipo num selo redondo no canto. */
export function IconAvatar(user, icon, system = false) {
  return m("span", {
    className: classList('CanelaUserMenu-iconAvatar', system || !user ? 'system-avatar' : 'user-avatar')
  }, user ? m(Avatar, {
    user: user
  }) : systemAvatar(), m("span", {
    className: "CanelaUserMenu-iconWrapper"
  }, m(Icon, {
    name: icon
  })));
}
/** O `<li>` do `menu-item` do Discourse. Fecha o menu ao seguir o link. */
export function MenuItem(attrs) {
  const external = attrs.href.includes('://');
  const content = [attrs.avatar, m("div", {
    className: "CanelaUserMenu-itemText"
  }, attrs.label ? m("span", {
    className: "CanelaUserMenu-label"
  }, attrs.label) : null, attrs.description ? m("span", {
    className: "CanelaUserMenu-description"
  }, attrs.description) : null)];
  const onclick = e => {
    attrs.onclick?.(e);

    // Abrir em outra aba não fecha nada.
    if (e.ctrlKey || e.metaKey || e.shiftKey || e.button === 1) return;
    userMenu.close();
  };
  return m("li", {
    className: classList('CanelaUserMenu-item', attrs.className, attrs.unread ? 'unread' : 'read')
  }, attrs.href ? m(Link, {
    href: attrs.href,
    external: external,
    title: attrs.title,
    onclick: onclick
  }, content) : m("button", {
    type: "button",
    className: "Button--ua-reset",
    title: attrs.title,
    onclick: onclick
  }, content));
}
export function NotificationItem(notification) {
  const view = describeNotification(notification);
  if (!view) return null;
  return MenuItem({
    className: `CanelaUserMenu-item--notification Notification--${notification.contentType()}`,
    unread: !notification.isRead(),
    href: view.href,
    title: view.title,
    avatar: IconAvatar(notification.fromUser(), view.icon),
    label: view.label,
    description: view.description,
    onclick: () => markNotificationRead(notification)
  });
}
flarum.reg.add('lcoy-roselle', 'forum/usermenu/notifications', { REPLY_TYPES: REPLY_TYPES,LIKE_TYPES: LIKE_TYPES,MESSAGE_TYPES: MESSAGE_TYPES,BOOKMARK_TYPES: BOOKMARK_TYPES,loadedNotifications: loadedNotifications,matches: matches,filteredNotifications: filteredNotifications,unreadCount: unreadCount,markNotificationRead: markNotificationRead,dismissNotifications: dismissNotifications,describeNotification: describeNotification,IconAvatar: IconAvatar,MenuItem: MenuItem,NotificationItem: NotificationItem, });